import React, { useState, useEffect } from 'react';
import { products, suppliers } from '../data/mockData';
import './addProductForm.css';

function AddProductForm({ addProduct }) {
    const [id, setProductnr] = useState("");
    const [productname, setProductname] = useState("");
    const [category, setCategory] = useState("");
    const [unit, setUnit] = useState("");
    const [sellprice, setSellprice] = useState("");
    const [supplier, setSupplier] = useState("");
    const [image, setImage] = useState("");

    // Handle Change
    const handleChange = (e) => {
        const { name, files } = e.target;
        if (name === "image") {
            setImage(files[0]); // Store the selected file in the image state
        }
    };

    // Handle the form submission
    const handleSubmit = (e) => {
        e.preventDefault();

        // Trim inputs and validate required fields
        const requiredFields = [id, productname, category, unit, sellprice, supplier];
        if (requiredFields.some(field => field.trim() === "")) {
            alert("Please fill in all fields");
            return;
        }

        // Convert quantity and price to numbers
        const parsedSellprice = sellprice.trim() !== "" && !isNaN(sellprice) ? parseFloat(sellprice) : NaN;



        if (isNaN(parsedSellprice) || parsedSellprice <= 0) {
            alert("Please enter a valid price");
            return;
        }

        useEffect(() => {
            async function fetchSuppliers() {
                try {
                    const response = await fetch("http://localhost:8080/suppliers");
                    if (!response.ok) throw new Error("Failed to fetch suppliers");
                    const data = await response.json();
                    setSuppliers(data);
                } catch (error) {
                    console.error("Error fetching suppliers:", error);
                }
            }

            fetchSuppliers();
        }, []);


        // Creating an object for the new product
        const newProduct = {
            id,
            productname,
            category,
            quantity: 0,
            unit,
            sellprice: parsedSellprice,
            supplier: suppliers.find(s => s.id === supplier),
            ...(image && { image }) // Add image if available
        };

        // Debugging output
        console.log("New Product:", newProduct);
        alert(`Product Added: ${JSON.stringify(newProduct, null, 2)}`);

        // Calling function onAddProduct
        addProduct(newProduct);

        // Clear the fields
        setProductnr("");
        setProductname("");
        setCategory("");
        setUnit("");
        setSellprice("");
        setSupplier("");
        setImage("");
    };

    return (
        <form onSubmit={handleSubmit}>

            <h1>Add a New Product</h1>

            <div className='formField'>
                <label>Product Name:</label>
                <input type="text" value={productname} onChange={(e) => setProductname(e.target.value)} className='shortInputField' />
            </div>

            <div className='twoFieldsHolder'>

                <div className='formField'>
                    <label>Category:</label>
                    <select
                        value={category}
                        onChange={(e) => setCategory(e.target.value)}
                        className='shortInputField'
                    >
                        <option value="">Select category</option>
                        {[...new Set(products.map(p => p.category))].map((cat, idx) => (
                            <option key={idx} value={cat}>{cat}</option>
                        ))}
                    </select>
                </div>

                <div className='formField'>
                    <button className='addBtn mt-4' type="button">Add category</button>
                </div>

            </div>

            <div className='twoFieldsHolder'>
                
                <div className='formField'>
                    <label>Price:</label>
                    <input type="text" value={sellprice} onChange={(e) => setSellprice(e.target.value)} className='longInputField' />
                </div>

                <div className='formField'>
                    <label>Unit:</label>
                    <input type="text" value={unit} onChange={(e) => setUnit(e.target.value)} className='shortInputField' />
                </div>
            </div>

            <div className='formField'>
                <label>Supplier:</label>
                <select
        value={supplier}
        onChange={(e) => setSupplier(e.target.value)}
        className='shortInputField'
    >
        <option value="">Select supplier</option>
        {suppliers.map(s => (
            <option key={s.suppliernr} value={s.suppliernr}>
                {s.name}
            </option>
        ))}
    </select>
</div>
            
            <div className='formField'>
                <label>Product Image:</label>
                <input type="file" accept={"image/products/"+ products.productnr} name="image" onChange={handleChange} className='longInputField' />
            </div>

            <button className='addBtn' type="submit">Add Product</button>

        </form>
    );
}

export default AddProductForm;
